import {Form as Material} from "./1Adding Interactivity/4UpdatingObjects"
import Root from "./1Adding Interactivity/4UpdatingObjects"
import Sub from "./subReLearn"
import "./ReLearn.css"
import { useState } from "react"

export default function () {
  const [val, setVal] = useState(1)
  return (
    <>
    <Form/>
    </>
  );
}

function Form() {
  const [value, setValue] = useState({ message: "wow", info: "real" });
  function onchange(e) {
    setValue({ ...value, message: e.target.value });
  }
  function onchangee(e) {
    setValue({ ...value, info: e.target.value });
  }
  return (
    <>
      <label>
        <input value={value.message} onChange={onchange} />
      </label>
      <label>
        {" "}
        <br />
        <input value={value.info} onChange={onchangee} />
      </label>
      <p>
        {value.message} {value.info}
      </p>
    </>
  );
}



// http://localhost:3000
